/// <summary>
/// MPJ_3863 - kscerri - 05/08/2021
/// Class <c>METCustTransListingUIBuilder</c> UI builder
/// </summary>
class METVendAuditReportUIBuilder extends SrsReportDataContractUIBuilder
{
    METVendAuditReportContract    contract;
    DialogField                   fromDateChange, toDateChange, vendAccount, vendGroup, legalEntity;
    container                     conContainer;


}

Method.Source:
    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// Builds dialog fields
    /// </summary>
    public void build()
    {
        contract = this.dataContractObject() as METVendAuditReportContract;

        fromDateChange  = this.addDialogField(methodStr(METVendAuditReportContract, parmFromDateChange), contract);
        vendAccount     = this.addDialogField(methodStr(METVendAuditReportContract, parmVendAccount), contract);
        legalEntity     = this.addDialogField(methodStr(METVendAuditReportContract, parmLegalEntity), contract);
        toDateChange    = this.addDialogField(methodStr(METVendAuditReportContract, parmToDateChange), contract);
        vendGroup       = this.addDialogField(methodStr(METVendAuditReportContract, parmVendGroup), contract);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// Maps dialog fields above to contract method
    /// </summary>
    public void postBuild()
    {
        super();

        contract = this.dataContractObject() as METVendAuditReportContract;

        fromDateChange = this.bindInfo().getDialogField(contract, methodStr(METVendAuditReportContract, parmFromDateChangE));
        vendAccount    = this.bindInfo().getDialogField(contract, methodStr(METVendAuditReportContract, parmVendAccount));
        toDateChange   = this.bindInfo().getDialogField(contract, methodStr(METVendAuditReportContract, parmToDateChange));
        vendGroup      = this.bindInfo().getDialogField(contract, methodStr(METVendAuditReportContract, parmVendGroup));
        legalEntity    = this.bindInfo().getDialogField(contract, methodStr(METVendAuditReportContract, parmLegalEntity));

        legalEntity.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METVendAuditReportUIBuilder, legalEntityLookup), this);
        vendAccount.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METVendAuditReportUIBuilder, vendAcclookup), this);
        vendGroup.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METVendAuditReportUIBuilder, vendGrouplookup), this);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// legal entity lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void legalEntityLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS = query.addDataSource(tableNum(companyinfo));

        tableQBDS.addSelectionField(fieldNum(companyinfo, DataArea));
        tableQBDS.addSelectionField(fieldNum(companyinfo, Name));
        tableQBDS.addOrderByField(fieldnum(companyinfo, DataArea));

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// Vendor table lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void vendAcclookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS =   query.addDataSource(tableNum(vendTable));
        query.allowCrossCompany(true);
        tableQBDS.addSelectionField(fieldNum(vendTable, AccountNum));
        tableQBDS.addSelectionField(fieldNum(vendTable, Party));
        tableQBDS.addSelectionField(fieldNum(vendTable, DataAreaId));

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// Vendor group lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void vendGrouplookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS =   query.addDataSource(tableNum(vendGroup));
        query.allowCrossCompany(true);

        tableQBDS.addSelectionField(fieldNum(vendGroup, VendGroup));
        tableQBDS.addSelectionField(fieldNum(vendGroup, Name));
        tableQBDS.addOrderByField(fieldnum(vendGroup, VendGroup));
        tableQBDS.orderMode(OrderMode::GroupBy);
        tableQBDS.addOrderByField(fieldnum(vendGroup, Name));
        tableQBDS.orderMode(OrderMode::GroupBy);

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

